bool isLowerCaseVowelString(const char* str) {
    int len = strlen(str);

    // Ignore leading whitespace
    int start = 0;
    while (start < len && isspace(str[start])) {
        start++;
    }

    // Ignore trailing whitespace
    int end = len - 1;
    while (end >= start && isspace(str[end])) {
        end--;
    }

    // Check if the string is empty or contains only whitespace
    if (start > end) {
        return false;
    }

    // Check if the string starts with a vowel letter
    char firstChar = tolower(str[start]);
    if (firstChar != 'a' && firstChar != 'e' && firstChar != 'i' && firstChar != 'o' && firstChar != 'u') {
        return false;
    }

    // Check if the string contains only lowercase alphabets
    for (int i = start + 1; i <= end; i++) {
        char c = str[i];
        if (!islower(c)) {
            return false;
        }
    }

    return true;
}

int main() {
    char str[100];
    printf("Enter a string: ");
    fgets(str, sizeof(str), stdin);

    // Remove trailing newline character from fgets
    int len = strlen(str);
    if (str[len - 1] == '\n') {
        str[len - 1] = '\0';
    }

    bool isLowerVowel = isLowerCaseVowelString(str);
