def apply_css_rule(css_rule, html_elements):
    new_html_elements = []
    for element in html_elements:
        if element["tag"] == "div" and element.get("class") == "content":
            for child in element["children"]:
                if child["tag"] == "p" and child.get("class") == "highlight":
                    child["style"] = css_rule.split("{")[1].split("}")[0]
        new_html_elements.append(element)
    return new_html_elements

