To create a full-stack web application with the specified features, you'll need to use various technologies and frameworks. Here's an example of how you can implement the application using Node.js, Express, MongoDB, and Nodemailer.

1. Set up the project:
   - Create a new directory for your project and navigate into it.
   - Run `npm init` to initialize a new Node.js project.
   - Install the required dependencies by running `npm install express mongoose nodemailer bcrypt validator dotenv`.

2. Create a file named `app.js` and set up the Express server:
```javascript
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcrypt');
const validator = require('validator');
const dotenv = require('dotenv');
const nodemailer = require('nodemailer');

dotenv.config();

const app = express();
app.use(express.json());

// Connect to the MongoDB database
mongoose.connect(process.env.DB_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Define a User schema and model
const userSchema = new mongoose.Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true },
  password: { type: String, required: true },
  phone: { type: String, required: true, unique: true },
  verified: { type: Boolean, default: false },
});

const User = mongoose.model('User', userSchema);

// Define the routes

// Register a new user
app.post('/register', async (req, res) => {
  const { name, email, password, phone } = req.body;

  // Client-side validation
  if (!validator.isEmail(email)) {
    return res.status(400).json({ error: 'Invalid email address' });
  }

  if (password.length < 8) {
    return res
      .status(400)
      .json({ error: 'Password should be at least 8 characters long' });
  }

  // Server-side validation
  try {
    const existingUser = await User.findOne({ email });
    if (existingUser) {
      return res.status(400).json({ error: 'Email already registered' });
    }

    const existingPhone = await User.findOne({ phone });
    if (existingPhone) {
      return res.status(400).json({ error: 'Phone number already registered' });
    }

    // Hash the password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Create a new user
    const newUser = new User({
      name,
      email,
      password: hashedPassword,
      phone,
    });

    await newUser.save();

    // Send verification email
    const transporter = nodemailer.createTransport({
      service: 'YourEmailService',
      auth: {
        user: process.env.EMAIL_USERNAME,
        pass: process.env.EMAIL_PASSWORD,
      },
    });

    const mailOptions = {
      from: process.env.EMAIL_FROM,
      to: email,
      subject: 'Account Verification',
      html: `<p>Please click the following link to verify your account:</p>
             <a href="${process.env.APP_URL}/verify/${newUser._id}">Verify Account</a>`,
    };

    transporter.sendMail(mailOptions, (error, info) => {
      if (error) {
        console.log('Error sending verification email:', error);
      } else {
        console.log('Verification email sent:', info.response);
      }
    });

    res.status(201).json({ message: 'Registration successful' });
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Verify user account
app.get('/verify/:id', async (req, res) => {
  try {
