    if (arr[low] > arr[high]) {
        std::swap(arr[low], arr[high]);
    }
    if (arr[mid] > arr[high]) {
        std::swap(arr[mid], arr[high]);
    }

    return &arr[mid];
}

int* getMedianPivot(int arr[], int low, int high) {
    int* medianPivot;
    medianPivot = findMedian(arr, low, high);
    std::swap(*medianPivot, arr[high]);
    return &arr[high];
}

int* quickSortWrapper(int arr[], int n) {
    quickSort(arr, 0, n - 1);
    return arr;
