            if score < 0 or score > 100:
                raise ValueError
            return score
        except ValueError:
            print("Error: Please enter a valid integer between 0 and 100.")

def calculate_average_score(scores):
    return sum(scores) / len(scores)

def get_subject_names_sorted(subject_names):
    return sorted(subject_names)

def display_student_info(name, subject_names, scores, average_score):
    print("\nStudent Name: {}".format(name))
    print("Subject Names: {}".format(", ".join(subject_names)))
    print("Scores: {}".format(", ".join(map(str, scores))))
    print("Average Score: {:.2f}".format(average_score))
    print("Max Score: {}".format(max(scores)))
    print("Min Score: {}".format(min(scores)))

def main():
    while True:
        num_subjects = get_positive_integer_input("Enter the number of subjects: ")
        subject_names = []
        scores = []

        for i in range(1, num_subjects + 1):
            subject_name = get_subject_name_input(i)
            subject_names.append(subject_name)
            score = get_score_input(subject_name)
            scores.append(score)

        subject_names_sorted = get_subject_names_sorted(subject_names)
        average_score = calculate_average_score(scores)

        display_student_info("John Doe", subject_names_sorted, scores, average_score)

        choice = input("Do you want to enter additional subjects? (Y/N): ")
        while choice.upper() not in ["Y", "N"]:
            print("Error: Please enter 'Y' or 'N'.")
            choice = input("Do you want to enter additional subjects? (Y/N): ")

        if choice.upper() == "N":
            break

if __name__ == "__main__":
    main()
